	TITLE 'QuickDraw Pictures--SlabStuff'****************************************************************** Pictures--Slab Stuff** This file contains all the code that needs the slab equates.***	 Copyright (C) 1986-1989*	 Apple Computer, Inc.*	 All Rights Reserved*** Change History** 29 Apr 87    Steven Glass** Error handling was added after every put and get call.*****************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:rect.equs'	include '::qd:qdequates:slab.equs'	include '::qd:qdequates:conics.equs'	include 'play.equs'	include '::qd:qdequates:qd.data.asm'	include 'pic.equs'********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/LINES'****************************************************************** Line Routines for	pictures.** Four opcodes are supported.**		     TotalSize**        opLine	    Point,    NewPoint       9*        opLineFrom	              NewPoint       5*        opShortL	    Point     dh,dv	         7*        opShortLFrom             dh,dv	         3************************************************************************************************************************************* rDrawLine** This is the routine which reads the line data from the* picture and draws	the line.****************************************************************** rDrawLine      startrDrawLine	PROC EXPORT	pha	; put 8 bytes on stack for the	pha	; end points of the	line being	pha	; drawn	pha	lda OpCodeToDo	; look at the real op code and	and #$0003	; mask off all but low two bits	asl a	tax	; use these to decide what to do	jmp (WhichOpTable,x)	Export WhichOpTableWhichOpTable	DC.W DoLong	DC.W DoLongFrom	DC.W DoShort	DC.W DoShortFromDoLong		;	jsr getpicword	bcs Error8	sta 1,s	jsr getpicword	bcs Error8	sta 3,sDoDestPt		;	jsr getpicword	bcs Error8	sta 5,s	jsr getpicword	bcs Error8	sta 7,s	bra ShareDoLongFrom		;	lda PenLoc	sta 1,s	lda PenLoc+2	sta 3,s	bra DoDestPtDoShort		;	jsr GetPicWord	bcs Error8	sta 1,s	jsr GetPicWord	bcs Error8	sta 3,sDodHdV		;	jsr GetPicWord	bcs Error8	tax	; save copy in x	and #$00FF	; look at low byte which is signed;		; integer containing offset	xba	; swap twice to set	neg condition	xba	; on bit 7	bpl NotNeg1	ora #$FF00	; was neg so extend	signNotNeg1		;	clc	; add sign extended	value to	adc 1,s	; starting point	sta 5,s	; and put in 5,s	txa	; now do other byte	and #$FF00	xba	bpl NotNeg2	ora #$FF00NotNeg2		;	clc	adc 3,s	sta 7,s	bra ShareDoShortFrom		;	lda PenLoc	sta 1,s	lda PenLoc+2	sta 3,s	bra DodHdV;-----------------------------------------------------------;; Error handling;Error8	plx	plx	plx	plx	rtsShare		;;------------------------------------------------------------;; Before mapping, update the penloc in the play state record.;	lda 5,s	sta PenLoc	lda 7,s	sta PenLoc+2	jsr MapThisRect	ldx QuickDrawD	pla	sta >Y1,x	sta >Rect2,x	pla	sta >X1,x	sta >rect2+2,x	pla	sta >Y2,x	sta >rect2+4,x	pla	sta >X2,x	sta >rect2+6,x	lda #0	sta >DrawVerb,x	phd	; save this d	txa	tcd	; set d to QD's d	lda #o_stdline	jsl callstdplay	pld	; restore d	rts	ENDP****************************************************************** wDrawLine** This is the routine that puts the line info into the* picture.****************************************************************** wDrawLine      STARTwDrawLine	PROC EXPORT	PushWord #PicLine	; start by putting base;		; opcode on the stack; compare starting point of line to last penloc in pic state; record.	lda Y1	ldy #o_PicPnLoc	cmp [TEMP2],y	bne NotFrom	lda X1	ldy #o_PicPnLoc+2	cmp [TEMP2],y	bne NotFrom; YesFrom	lda 1,s	; set bit on of opcode to mean	ora #$0001	; from.	sta 1,sNotFrom		;;; Now check to see if the displacement is less than -128 or	127;	lda Y2	sec	sbc Y1	clc	adc #128	cmp #256	bcs BigDisplacement	lda X2	sec	sbc X1	clc	adc #128	cmp #256	bcs BigDisplacement; Small Displacement so set next bit in	opcode	lda 1,s	ora #$0002	sta 1,sBigDisplacement		;; Put the opcode into the picture;	lda 1,s	jsr PutPicWord	bcs Error2; now look at the opcode we put	lda 1,s	ror a	bcs SkipFirstPoint	lda Y1	ldx X1	jsr PutPicLong	bcs Error2SkipFirstPoint		;	lda 1,s	ror a	ror a	bcs DoDisplacement	lda Y2	ldx X2	jsr PutPicLong	bcs Error2	bra Done;------------------------------------------------------------;; Error handling;Error4	plx	plxError2	plx	plxError0	rts;------------------------------------------------------------DoDisplacement		;	lda Y2	; figure dV and put	8 bit	sec	; result on stack	sbc Y1	and #$00FF	pha	lda X2	; figure dH and merge 8 bit	sec	; result with value	on stack	sbc X1	and #$00FF	xba	ora 1,s	jsr PutPicWord	bcs Error4	pla	; clear this from stackDone	pla	; clear opcode from	stack	jsr DerefTempToTemp2;; update the PnLoc in the picture state	record.;	ldy #o_PicPnLoc	lda Y2	sta [TEMP2],y	iny	iny	lda X2	sta [TEMP2],y	rts	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/RECTS'****************************************************************** Picture Rectangle	Stuff** There are 10 kinds of rectangle opcodes.** All of them have the same high nibble	the low nibble is* arranged to have the verb in the low three bits and a* flag relating to the rectangle to use	in the high bit of* the low nibble.*********************************************************************************************************************************** rDrawRect** This reads the rectangle out of the picture and draws it.****************************************************************** rDrawRect      startrDrawRect	PROC EXPORT	lda OpCodeToDo	; see if the rect is already here	and #$0008	; in the stack frame	beq RectInPicture	pei TheRect+6	pei TheRect+4	pei TheRect+2	pei TheRect	bra ShareRectInPicture		;	pha	pha	pha	pha	tsc	; read the rect out	of the picture	inc a	; onto the stack	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error8	jsr MapThisRect	; map itShare		;	ldx QuickDrawD	pla	; put it on zero page	sta TheRect	; and update the rect in play	sta >Y1,x	; state record	pla	sta TheRect+2	sta >X1,x	pla	sta TheRect+4	sta >Y2,x	pla	sta TheRect+6	sta >X2,x	lda OpCodeToDo	; get verb out of op code	and #$0007	sta >DrawVerb,x	phd	txa	tcd	lda #o_StdRect	; draw it	jsl CallStdPlay	pld	rtsError8	plx	plx	plx	plx	rts	ENDP****************************************************************** wDrawRect** This is the routine which puts the rect in the picture****************************************************************** wDrawRect      startwDrawRect	PROC EXPORT	lda #RectNoun	; put in the rect noun	brl PutPicRect	ENDP****************************************************************** PutPicRect** Creates the right	opcode for the operation being performed* by merging the Noun passed in the a-reg with the verb in* DrawVerb.** Also looks at the	rect to be drawn to	see if it is the same* as TheRect in the	picture state record.  If it is we add* 8 to the op code and do not bother putting the rect in* the picture.****************************************************************** PutPicRect     STARTPutPicRect	PROC EXPORT	sta DrawNoun	; put it in DrawNoun for now	ldx #0	ldy #o_PicTheRect	pea 0	; put 0 on stack to	indicate sameCheckRectLoop	lda Y1,x	cmp [TEMP2],y	beq TheSame	sta [TEMP2],y	; update therect	tya	; set flag on stack	to nonzero	sta 1,sTheSame	inx	inx	iny	iny	cpx #8	bcc CheckRectLoop	pla	beq RectWasSame	lda DrawNoun	ora DrawVerb	jsr PutPicWord	bcs Error0	pea 0	; and finally the rect	tdc	clc	adc #Y1	pha	PushWord #8	jsl CallPutPicError0		;	rtsRectWasSame		;	lda DrawNoun	ora DrawVerb	ora #$0008	jsr PutPicWord	rts	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/ROUNDRECTS'****************************************************************** Picture RRect Stuff** There are 10 kinds of RRect opcodes.** All of them have the same high nibble	the low nibble is* arranged to have the verb in the low three bits and a* flag relating to the rectangle to use	in the high bit of* the low nibble.*********************************************************************************************************************************** rDrawRRect** This reads the RRect out of the picture and draws it.****************************************************************** rDrawRRect      startrDrawRRect	PROC EXPORT	lda OpCodeToDo	; see if the rect is already here	and #$0008	; in the stack frame	beq RectInPicture	pei TheRect+6	pei TheRect+4	pei TheRect+2	pei TheRect	bra ShareRectInPicture		;	pha	pha	pha	pha	tsc	; read the rect out	of the picture	inc a	; onto the stack	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error8	jsr MapThisRect	; map itShare		;	ldx QuickDrawD	pla	; put it on zero page	sta TheRect	; and update the rect in play	sta >Y1,x	; state record	sta >OvalTop+512,x	pla	sta TheRect+2	sta >X1,x	sta >OvalTop+512+2,x	pla	sta TheRect+4	sta >Y2,x	sta >OvalTop+512+4,x	pla	sta TheRect+6	sta >X2,x	sta >OvalTop+512+6,x	lda OpCodeToDo	; get verb out of op code	and #$0007	sta >DrawVerb,x	lda OvalSize	; get oval size out	of play state	sta >OvalHeight+512,x ; record	lda OvalSize+2	sta >OvalWidth+512,x	lda #0	sta >StartAngle,x	lda #360	sta >ArcAngle,x	phd	txa	tcd	lda #o_StdRRect	; draw it	jsl CallStdPlay	pld	rtsError8	plx	plx	plx	plx	rts	ENDP****************************************************************** wDrawRRect** This is the routine which puts the RRect in the picture****************************************************************** wDrawRRect     STARTwDrawRRect	PROC EXPORT	ldy #o_PicOvSize	lda [TEMP2],y	ldx #512	cmp OvalHeight,x	bne SizeChanged	iny	iny	lda [TEMP2],y	cmp OvalWidth,x	beq SizeSameSizeChanged	lda #PicOvSize	jsr PutPicWord	bcs Error0	ldx #512	lda OvalWidth,x	tay	lda OvalHeight,x	tyx	jsr PutPicLong	bcs Error0SizeSame	lda #RRectNoun	; put in the RRect noun	brl PutPicRectError0	rts	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/OVALS'****************************************************************** Picture Oval Stuff** There are 10 kinds of Oval opcodes.** All of them have the same high nibble	the low nibble is* arranged to have the verb in the low three bits and a* flag relating to the rectangle to use	in the high bit of* the low nibble.*********************************************************************************************************************************** rDrawOval** This reads the oval out of the picture and draws it.****************************************************************** rDrawOval      startrDrawOval	PROC EXPORT	lda OpCodeToDo	; see if the rect is already here	and #$0008	; in the stack frame	beq RectInPicture	pei TheRect+6	pei TheRect+4	pei TheRect+2	pei TheRect	bra ShareRectInPicture		;	pha	pha	pha	pha	tsc	; read the rect out	of the picture	inc a	; onto the stack	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error8	jsr MapThisRect	; map itShare		;	ldx QuickDrawD	lda 5,s	sec	sbc 1,s	sta >OvalHeight+512,x	lda 7,s	sec	sbc 3,s	sta >OvalWidth+512,x	lda #360	sta >ArcAngle,x	lda #0	sta >StartAngle,x	pla	; put it on zero page	sta TheRect	; and update the rect in play	sta >Y1,x	; state record	sta >OvalTop+512,x	pla	sta TheRect+2	sta >X1,x	sta >OvalTop+512+2,x	pla	sta TheRect+4	sta >Y2,x	sta >OvalTop+512+4,x	pla	sta TheRect+6	sta >X2,x	sta >OvalTop+512+6,x	lda OpCodeToDo	; get verb out of op code	and #$0007	sta >DrawVerb,x	phd	txa	tcd	lda #o_StdOval	; draw it	jsl CallStdPlay	pld	rtsError8	plx	plx	plx	plx	rts	ENDP****************************************************************** wDrawOval** This is the routine which puts the Oval in the picture****************************************************************** wDrawOval      startwDrawOval	PROC EXPORT	lda #OvalNoun	; put in the Oval noun	brl PutPicRect	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/ARCS'****************************************************************** Picture Arc Stuff** There are 10 kinds of Arc opcodes.** All of them have the same high nibble	the low nibble is* arranged to have the verb in the low three bits and a* flag relating to the rectangle to use	in the high bit of* the low nibble.*********************************************************************************************************************************** rDrawArc** This reads the Arc out of the picture	and draws it.****************************************************************** rDrawArc       startrDrawArc	PROC EXPORT	lda OpCodeToDo	; see if the rect is already here	and #$0008	; in the stack frame	beq RectInPicture	pei TheRect+6	pei TheRect+4	pei TheRect+2	pei TheRect	bra ShareRectInPicture		;	pha	pha	pha	pha	tsc	; read the rect out	of the picture	inc a	; onto the stack	pea 0	pha	PushWord #8	jsl CallGetPic	bcs Error8	jsr MapThisRect	; map itShare		;	jsr GetPicLong	; get the arc angle	and start angle	bcs Error8	txy	ldx QuickDrawD	sta >StartAngle,x	tya	sta >ArcAngle,x	lda 5,s	sec	sbc 1,s	sta >OvalHeight+512,x	lda 7,s	sec	sbc 3,s	sta >OvalWidth+512,x	pla	; put it on zero page	sta TheRect	; and update the rect in play	sta >Y1,x	; state record	sta >OvalTop+512,x	pla	sta TheRect+2	sta >X1,x	sta >OvalTop+512+2,x	pla	sta TheRect+4	sta >Y2,x	sta >OvalTop+512+4,x	pla	sta TheRect+6	sta >X2,x	sta >OvalTop+512+6,x	lda OpCodeToDo	; get verb out of op code	and #$0007	sta >DrawVerb,x	phd	txa	tcd	lda #o_StdArc	; draw it	jsl CallStdPlay	pld	rtsError8	plx	plx	plx	plx	rts	ENDP****************************************************************** wDrawArc** This is the routine which puts the Arc in the picture****************************************************************** wDrawArc       startwDrawArc	PROC EXPORT	lda #ArcNoun	; put in the Arc noun	jsr PutPicRect	bcs Error	lda StartAngle	; now add the start	and arc angles	ldx ArcAngle	jsr PutPicLongError	rts	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/POLYS'****************************************************************** rDrawPoly** This reads the region out of the picture and draws it.****************************************************************** rDrawPoly      STARTrDrawPoly	PROC EXPORT	jsr GetPicRgn	; treat this just like a region	bcs error	phx	; save result on stack here	pha	lda 3,s	; push handle on stack again	pha	lda 3,s	pha	jsr PushRectPtrs	; push the rectangle pointers on	_MapPoly	ldx QuickDrawD	; put handle to poly on quickdraw's	lda 1,s	; direct page	sta >RgnhandleA,x	sta >RgnhandleB,x	sta >RgnhandleC,x	lda 3,s	sta >RgnhandleA+2,x	sta >RgnhandleB+2,x	sta >RgnhandleC+2,x	lda OpCodeToDo	; put the draw verb	on quickdraw's	and #$0007	; direct page	sta >DrawVerb,x	phd	txa	tcd	lda #o_stdPoly	jsl callstdPlay	pld	_disposehandle	; using handle on stack dispose itError		;	rts	ENDP****************************************************************** wDrawPoly** This is the routine which puts the Poly in the picture****************************************************************** wDrawPoly      STARTwDrawPoly	PROC EXPORT	lda #PolyNoun	; put the noun and verb in pic	ldx RgnHandleA	ldy RgnHandleA+2	jsr PutPicRgn	rts	ENDP********************************************************************************************************************************************	title 'QuickDraw Pictures--Slab Stuff     slabs/REGIONS'****************************************************************** rDrawRgn** This reads the region out of the picture and draws it.****************************************************************** rDrawRgn       STARTrDrawRgn	PROC EXPORT	jsr GetPicRgn	bcs Error0	phx	; save result on stack here.	pha	lda 3,s	; push handle on stack again	pha	lda 3,s	pha	jsr mapThisRgn	bcs Error4	ldx QuickDrawD	; Put the region handle on quickdraw's	lda 1,s	; direct page.	sta >RgnhandleC,x	lda 3,s	sta >RgnhandleC+2,x	lda OpCodeToDo	; put the draw verb	on quickdraw's	and #$0007	; direct page	sta >DrawVerb,x	phd	txa	tcd	lda #o_stdRgn	jsl callstdPlay	pld	_disposehandle	; using handle on stack dispose itError0		;	rtsError4	plx	plx	rts	ENDP****************************************************************** wDrawRgn** This is the routine which puts the Rgn in the picture****************************************************************** wDrawRgn       STARTwDrawRgn	PROC EXPORT	lda #RgnNoun	; put the noun and verb in pic	ldx RgnHandleC	ldy RgnHandleC+2	jsr PutPicRgn	rts	ENDP****************************************************************** PutPicRgn**     Inputs:     a-reg noun*                 x-reg low word of handle*                 y-reg high word of handle** This routine has three entry points.	In the main entry* the a-reg is merged with the draw verb.  In PutPicRgnB* The opword is unchanged.  In PutPicRgnC, no op word is* put in the picture.** No values on QuickDraw's zero page are affected by this* routine.****************************************************************** PutPicRgn      STARTPutPicRgn	PROC EXPORTOrigD	equ 1TheRgnH	equ 3TheRgnPtr	equ 7	ora DrawVerb	Export PutPicRgnBPutPicRgnB	phy	; put the handle on	stack so can	phx	; deref and get size of rgn	phy	phx	jsr PutPicWord	; put the verb into	the pic	bcs Error8JoinRest		;	phd	; save the direct reg	tsc	; turn stack into direct page	tcd	ldy #4	; deref and lock it	lda [TheRgnH],y	ora #$8000	sta [TheRgnH],y	dey	dey	lda [TheRgnH],y	sta TheRgnPtr+2	lda [TheRgnH]	sta TheRgnPtr	pei TheRgnPtr+2	; push the pointer to rgn data on	pei TheRgnPtr	; stack	lda [TheRgnPtr]	; Get Size of region in a-reg	pha	lda OrigD	; put back the orig	direct for this	tcd	; call	jsl CallPutPic	; put it all in the	picture	bcs Error8d	tsc	tcd	ldy #4	; unlock the region	lda [TheRgnH],y	and #$7FFF	sta [TheRgnH],y	pld	; restore direct	pla	; clear off the 8 bytes put on	pla	; earlier.	pla	pla	clc	lda #0	rts	; doneError8d	pldError8	plx	plx	plx	plxError0	rts	Export PutPicRgnCPutPicRgnC	phy	phx	phy	phx	bra JoinRest	ENDP****************************************************************** GetPicRgn****************************************************************** GetPicRgn      STARTGetPicRgn	PROC EXPORT	jsr getpicword	; read size	bcs Error0	pha	; save size on stack	jsr MyWNewHandle	bcs Error2	phx	; save this on stack	pha	sta TempDataPtr	stx TempDataPtr+2	jsr DerefTempDataPtr	lda 5,s	; get size off stack from above handle	sta [TempDataPtr]	; put in new region	tay	; save in y too.	lda TempDataPtr	clc	adc #2	tax	lda TempDataPtr+2	bcc NoCarry	inc aNoCarry	pha	phx	dey	; first 2 bytes have already been	dey	; read	phy	jsl CallGetPic	bcs Error4	pla	; get handle off stack to return	plxError2		;	ply	; finally, get size	off stackError0	rtsError4	plx	; get handle off stack into	ply	; y and x	pha	; put error code on	stack	phy	; dispose handle	phx	_DisposeHandle	pla	; get back error code	sec	; set carry and quit.	rts	ENDP	END